var publicUrl=(Environment.GetEnvironmentVariable("LOLIABLOOM_PUBLIC_URL")??"http://localhost:8080").TrimEnd('/');
var clientId=Environment.GetEnvironmentVariable("LOLIA_OAUTH_CLIENT_ID")??"3k9iwlin05pwdv7g";
var builder=WebApplication.CreateBuilder(args);
builder.Services.AddHttpContextAccessor();builder.Services.AddAntiforgery(o=>{o.Cookie.Name="LoliaBloom.Csrf";o.Cookie.HttpOnly=true;o.Cookie.SameSite=SameSiteMode.Strict;o.Cookie.SecurePolicy=publicUrl.StartsWith("https://",StringComparison.OrdinalIgnoreCase)?CookieSecurePolicy.Always:CookieSecurePolicy.SameAsRequest;o.FormFieldName="csrf";});
builder.Services.AddAuthentication(CookieAuthenticationDefaults.AuthenticationScheme).AddCookie(o=>{o.Cookie.Name="LoliaBloom.Auth";o.Cookie.HttpOnly=true;o.Cookie.SameSite=SameSiteMode.Lax;o.Cookie.SecurePolicy=publicUrl.StartsWith("https://",StringComparison.OrdinalIgnoreCase)?CookieSecurePolicy.Always:CookieSecurePolicy.SameAsRequest;o.ExpireTimeSpan=TimeSpan.FromHours(12);o.SlidingExpiration=true;o.LoginPath="/login";});
builder.Services.AddAuthorization();builder.Services.AddDataProtection().PersistKeysToFileSystem(new DirectoryInfo(Path.Combine(data,"keys"))).SetApplicationName("LoliaBloom");builder.Services.AddSingleton(sp=>sp.GetRequiredService<IDataProtectionProvider>().CreateProtector("LoliaBloom.data.v1"));
builder.Services.AddSingleton(sp=>new Store(data,sp.GetRequiredService<Microsoft.AspNetCore.DataProtection.IDataProtector>()));builder.Services.AddSingleton<OAuthTokens>();builder.Services.AddSingleton<OAuthFlow>();builder.Services.AddSingleton<TunnelManager>();builder.Services.AddHostedService(sp=>sp.GetRequiredService<TunnelManager>());builder.Services.AddSingleton<LinuxTraffic>();builder.Services.AddHostedService(sp=>sp.GetRequiredService<LinuxTraffic>());builder.Services.AddSingleton<FrpUpdater>();
var app=builder.Build();app.Use(async(ctx,next)=>{ctx.Response.Headers.XContentTypeOptions="nosniff";ctx.Response.Headers.XFrameOptions="DENY";ctx.Response.Headers.ReferrerPolicy="no-referrer";ctx.Response.Headers.ContentSecurityPolicy="default-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'; img-src 'self' data:";await next();});app.UseAuthentication();app.UseAuthorization();
app.MapGet("/health",()=>Results.Json(new{status="ok",version="0.7.0"}));
app.MapGet("/api/live",(LinuxTraffic traffic)=>Results.Json(traffic.Rate)).RequireAuthorization();
app.MapGet("/login",(HttpContext c,IAntiforgery af)=>LoginPage(c,af,adminPassword));
app.MapPost("/login",async(HttpContext c,IAntiforgery af)=>{if(!await ValidCsrf(c,af))return Results.BadRequest("Invalid CSRF token");var form=await c.Request.ReadFormAsync();if(!PasswordOk(form["password"].ToString(),adminPassword))return Results.Content(LoginHtml(c,af,"密码不正确"),"text/html; charset=utf-8");await c.SignInAsync(CookieAuthenticationDefaults.AuthenticationScheme,new ClaimsPrincipal(new ClaimsIdentity(new[]{new Claim(ClaimTypes.Name,"admin")},CookieAuthenticationDefaults.AuthenticationScheme)));return Results.Redirect("/");});
app.MapGet("/auth/start",[Authorize] (OAuthFlow oauth)=>{var uri=oauth.Begin();return Results.Redirect(uri);});
app.MapGet("/auth/callback",async(string? code,string? state,string? error,OAuthFlow oauth,OAuthTokens tokens)=>{if(!string.IsNullOrWhiteSpace(error))return Results.Content($"<p>官网授权失败：{E(error)}</p><a href='/login'>返回</a>","text/html; charset=utf-8");try{var token=await oauth.Complete(code,state);await tokens.Save(token);return Results.Content("<!doctype html><html lang=zh-CN><meta charset=utf-8><title>已连接</title><meta name=viewport content='width=device-width'><body style='font:16px system-ui;background:#f8f4f9;color:#35283a'><main style='max-width:520px;margin:12vh auto;background:white;padding:30px;border-radius:18px'><h2>洛链映射账号已连接</h2><p>请回到原来已登录的管理页面并点击“同步云端隧道”。</p><a href='/login'>打开管理页面</a></main></body></html>","text/html; charset=utf-8");}catch(Exception ex){return Results.Content($"<main><h2>OAuth 授权失败</h2><p>{E(ex.Message)}</p><a href='/login'>返回管理台</a></main>","text/html; charset=utf-8");}});
app.MapPost("/logout",async(HttpContext c,IAntiforgery af)=>{if(!await ValidCsrf(c,af))return Results.BadRequest("Invalid CSRF token");await c.SignOutAsync();return Results.Redirect("/login");}).RequireAuthorization();
app.MapGet("/",async(HttpContext ctx,IAntiforgery af,Store store,OAuthTokens auth,TunnelManager tunnels,LinuxTraffic traffic,FrpUpdater frp)=>{var list=store.List;var model=list.Select(t=>new TunnelView(t.Id,t.Name,t.AutoStart,tunnels.IsRunning(t.Id),t.Type,t.Node,t.LocalAddress,t.RemoteAddress,t.Description,MetricsSource:"容器网络接口汇总（含管理网页流量）")).ToArray();var totals=new Dictionary<string,TrafficSample>();if(auth.Connected){try{var api=new LoliaApi(new HttpClient{Timeout=TimeSpan.FromSeconds(20)},auth.GetAccessToken);foreach(var item in list){try{totals[item.Id]=await api.Traffic(item.CloudName??item.Name);}catch{}}}catch{}}
 var info=frp.Installed;var csrf=af.GetAndStoreTokens(ctx).RequestToken??"";var notice=ctx.Request.Query["notice"].ToString();return Results.Content(Dashboard(true,auth.Connected,model,totals,csrf,notice,info,traffic.Rate),"text/html; charset=utf-8");}).RequireAuthorization();
app.MapPost("/sync",async(HttpContext c,IAntiforgery af,Store store,OAuthTokens auth,TunnelManager manager)=>{if(!await ValidCsrf(c,af))return Results.BadRequest("Invalid CSRF token");try{var api=new LoliaApi(new HttpClient{Timeout=TimeSpan.FromSeconds(30)},auth.GetAccessToken);var clouds=await api.Tunnels();var old=store.List.ToDictionary(x=>x.Id);var next=new List<Tunnel>();foreach(var x in clouds){old.TryGetValue(x.Id,out var prior);string? key=prior?.Credential;try{key=await api.TunnelToken(x.CloudName);}catch{}next.Add(new(x.Id,x.Label,prior?.AutoStart??false,x.Type,x.Node,x.LocalAddress,x.RemoteAddress,x.Remark,key,x.CloudName));}store.Save(next);manager.Reload();return Results.Redirect("/?notice=云端隧道已同步");}catch(Exception ex){return Results.Redirect("/?notice="+Uri.EscapeDataString("同步失败："+ex.Message));}}).RequireAuthorization();
app.MapPost("/tunnel/{id}/start",async(string id,HttpContext c,IAntiforgery af,TunnelManager m)=>{if(!await ValidCsrf(c,af))return Results.BadRequest("Invalid CSRF token");var ok=m.Start(id);return Results.Redirect("/?notice="+Uri.EscapeDataString(ok?"已发送启动请求":"启动失败，请先同步隧道并检查凭据与 FRP 日志"));}).RequireAuthorization();
app.MapPost("/tunnel/{id}/stop",async(string id,HttpContext c,IAntiforgery af,TunnelManager m)=>{if(!await ValidCsrf(c,af))return Results.BadRequest("Invalid CSRF token");m.Stop(id);return Results.Redirect("/?notice=隧道已停止");}).RequireAuthorization();
app.MapPost("/tunnel/{id}/auto",async(string id,string? enabled,HttpContext c,IAntiforgery af,Store store,TunnelManager m)=>{if(!await ValidCsrf(c,af))return Results.BadRequest("Invalid CSRF token");if(!bool.TryParse(enabled,out var value))return Results.BadRequest("Invalid switch value");var t=store.List.FirstOrDefault(x=>x.Id==id);if(t==null)return Results.NotFound();store.Save(store.List.Select(x=>x.Id==id?x with{AutoStart=value}:x));if(!value)m.CancelStartup(id);return Results.Redirect("/?notice="+Uri.EscapeDataString(value?"已开启开机连接":"已关闭开机连接；不会停止当前隧道"));}).RequireAuthorization();
app.MapPost("/frp/update",async(HttpContext c,IAntiforgery af,FrpUpdater updater,TunnelManager manager)=>{if(!await ValidCsrf(c,af))return Results.BadRequest("Invalid CSRF token");try{return Results.Redirect("/?notice="+Uri.EscapeDataString(await updater.Update(manager)));}catch(Exception ex){return Results.Redirect("/?notice="+Uri.EscapeDataString("FRP 更新失败："+ex.Message));}}).RequireAuthorization();
app.Run();

static string Dashboard(bool logged,bool connected,IReadOnlyList<TunnelView> items,Dictionary<string,TrafficSample> totals,string csrf,string notice,string frp,LinuxTrafficRate rate){
 var rows=string.Join("",items.Select(t=>{totals.TryGetValue(t.Id,out var total);var toggle=$"<form method=post action='/tunnel/{E(t.Id)}/auto'><input type=hidden name=csrf value='{E(csrf)}'><input type=hidden name=enabled value='{(!t.AutoStart).ToString().ToLowerInvariant()}'><button class='switch {(t.AutoStart?"on":"")}' title='下次服务启动时生效' aria-label='开机连接 {(t.AutoStart?"已开":"已关")}'></button></form>";var action=$"<form method=post action='/tunnel/{E(t.Id)}/{(t.Running?"stop":"start")}'><input type=hidden name=csrf value='{E(csrf)}'><button class='action {(t.Running?"soft":"")}'>{(t.Running?"停止":"启动")}</button></form>";return $"<tr><td><b>{E(t.Name)}</b><small>{E(t.LocalAddress??"—")}</small></td><td><span class='address'>{E(t.RemoteAddress??"—")}</span><small>{E(t.Type??"")} · {E(t.Node??"")}</small></td><td><span class='state {(t.Running?"green":"red")}'>{(t.Running?"运行中":"已停止")}</span></td><td>{toggle}<small>{(t.AutoStart?"已开启":"已关闭")}</small></td><td>{action}</td><td>{Fmt(t.DownloadBytesPerSecond)}/s <small>{Fmt(t.UploadBytesPerSecond)}/s</small></td><td>{Fmt(total?.In)} <small>{Fmt(total?.Out)}</small></td></tr>";}));
 var chart=Chart(rate.DownloadHistory,"#cf538f","downloadChart");var uploadChart=Chart(rate.UploadHistory,"#8565a5","uploadChart");var cloudAction=logged?connected?"<form method=post action='/sync'><input type=hidden name=csrf value='"+E(csrf)+"'><button class='button secondary'>同步云端隧道</button></form>":"<a class='button secondary' href='/auth/start'>连接洛链映射账号</a>":"";var signed=logged?"<form method=post action='/logout'><input type=hidden name=csrf value='"+E(csrf)+"'><button class='link'>退出管理</button></form>":"<a class='button' href='/login'>管理员登录</a>";var update=logged?$"<form method=post action='/frp/update'><input type=hidden name=csrf value='{E(csrf)}'><button class='button secondary'>检查 / 更新 FRP · {E(frp)}</button></form>":"";
 return $$"""
<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>洛链绽放</title><style>
*{box-sizing:border-box}body{margin:0;background:#f8f4f9;color:#35283a;font:15px system-ui,'Microsoft YaHei',sans-serif}.shell{max-width:1420px;margin:auto;padding:25px}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:25px}.brand{display:flex;align-items:center;gap:13px}.logo{background:#f6e8f0;border-radius:13px;padding:10px;color:#d74787;font-size:21px}.brand small,.muted,small{color:#a38d9f}.brand small{letter-spacing:3px}.user{display:flex;gap:10px;align-items:center}h1{font-size:29px;margin:4px 0}p{margin:6px 0 0}.button,button{border:0;border-radius:11px;padding:11px 16px;background:#d74787;color:#fff;font-weight:650;text-decoration:none;cursor:pointer;font-size:13px}.secondary{background:#fff;color:#664b66;border:1px solid #ecdfeb}.link{background:transparent;color:#8b7189}.cards{display:grid;grid-template-columns:1fr 1fr .8fr;gap:15px;margin:24px 0}.card,.panel{background:#fff;border-radius:18px;padding:19px;box-shadow:0 8px 24px #42214008}.label{font-size:12px;color:#a18c9d}.value{font-size:27px;font-weight:650;margin:6px 0}.pink{color:#cf538f}.purple{color:#8565a5}svg{display:block;width:100%;height:65px;overflow:visible}.grid{stroke:#efe6ef;stroke-width:1}.line{fill:none;stroke:#cf538f;stroke-width:2.5;stroke-linecap:round;stroke-linejoin:round}.line2{stroke:#8565a5}.panel{padding:21px;overflow:hidden}.panelhead{display:flex;justify-content:space-between;align-items:center;gap:15px}.tools{display:flex;gap:9px;flex-wrap:wrap}table{border-collapse:collapse;width:100%;margin-top:17px;min-width:870px}th{text-align:left;padding:13px 11px;background:#fcf8fb;color:#988696;font-weight:500;font-size:12px}td{padding:14px 11px;border-bottom:1px solid #f1eaf0;font-size:13px;vertical-align:middle}td small{display:block;margin-top:5px}.address{color:#be467d;word-break:break-all}.state{font-size:12px}.state:before{content:'●';font-size:10px;margin-right:7px}.green{color:#299b71}.red{color:#d66c73}.switch{width:48px;height:27px;border-radius:20px;background:#e8e0e9;padding:3px;position:relative}.switch:after{content:'';position:absolute;left:3px;top:3px;width:21px;height:21px;background:white;border-radius:50%;transition:.18s}.switch.on{background:#d74787}.switch.on:after{left:24px}.td form{margin:0}.action{padding:8px 13px}.soft{background:#856b86}.notice{background:#fff2d5;border:1px solid #ead5a6;color:#89622d;border-radius:12px;padding:12px 15px;margin-bottom:15px}.banner{color:#958397;font-size:12px;margin-top:15px}.empty{text-align:center;padding:40px;color:#a38d9f}.footer{margin-top:20px;color:#a38d9f;font-size:12px}.login{max-width:420px;margin:9vh auto;padding:30px}.login input{width:100%;padding:12px;border:1px solid #ebdfeb;border-radius:10px;margin:14px 0}form{margin:0}@media(max-width:850px){.shell{padding:15px}.cards{grid-template-columns:1fr 1fr}.cards .card:last-child{grid-column:span 2}.top{align-items:flex-start;gap:15px}.brand small{display:none}.panel{overflow-x:auto}.panelhead{align-items:flex-start;flex-direction:column}}
</style><div class="shell"><header class="top"><div class="brand"><div class="logo">✿</div><div><b>洛链绽放</b><br><small>LOLIA BLOOM</small></div></div><div class="user">{{(logged?"已登录管理页面":"")}} {{signed}}</div></header>
<h1>连接，从这里绽放。</h1><p class="muted">Linux 网页管理 · Docker 部署 · 隧道在容器后台运行</p>{{(notice.Length>0?$"<div class='notice' style='margin-top:18px'>{E(notice)}</div>":"")}}
<section class="cards"><div class="card"><div class="label">↓ 本地网络下载 · 实时</div><div class="value pink" id="downloadRate">{{Fmt(rate.Download)}}/s</div>{{chart}}</div><div class="card"><div class="label">↑ 本地网络上传 · 实时</div><div class="value purple" id="uploadRate">{{Fmt(rate.Upload)}}/s</div>{{uploadChart}}<div class="banner">容器网络接口汇总，包含管理网页访问流量</div></div><div class="card"><div class="label">◉ 正在运行</div><div class="value">{{items.Count(t=>t.Running)}} / {{items.Count}}</div><div class="banner">FRP {{E(frp)}} · 自动恢复已启用</div></div></section>
<section class="panel"><div class="panelhead"><div><b style="font-size:18px">我的隧道</b><div class="banner">开机连接逐条设置 · 关闭开关不会停止当前隧道</div></div><div class="tools">{{cloudAction}} {{update}}</div></div><table><thead><tr><th>隧道 / 本地服务</th><th>访问地址</th><th>状态</th><th>开机连接</th><th>操作</th><th>下载 / 上传</th><th>累计流量 ↓ / ↑</th></tr></thead><tbody>{{(rows.Length>0?rows:"<tr><td colspan='7' class='empty'>登录并同步云端隧道后，它们会显示在这里。</td></tr>")}}</tbody></table><div class="footer">开机连接在 Docker 容器重启后自动尝试；请在 Docker 设置自动重启策略。</div></section><div class="footer">洛链绽放社区客户端 · 非官方项目 · 仅限非商业用途，商业使用需取得书面授权</div></div><script>
const fmt=n=>{if(n==null)return '—';let u=['B','KB','MB','GB','TB'],i=0;while(n>=1024&&i<u.length-1){n/=1024;i++}return n.toFixed(2).replace(/\.?0+$/,'')+' '+u[i]};
function draw(id,values){let node=document.getElementById(id);if(!node)return;let max=Math.max(1,...values),pts=values.map((v,i)=>`${i*100/Math.max(1,values.length-1)},${58-v/max*52}`).join(' ');node.setAttribute('points',pts)}
async function poll(){try{let r=await fetch('/api/live',{cache:'no-store'});if(!r.ok)return;let x=await r.json();document.getElementById('downloadRate').textContent=fmt(x.download)+' /s';document.getElementById('uploadRate').textContent=fmt(x.upload)+' /s';draw('downloadChart',x.downloadHistory||[]);draw('uploadChart',x.uploadHistory||[])}catch{}}
setInterval(poll,1000);</script></html>
""";
}
static string Chart(IReadOnlyList<double> values,string color,string id){var vals=values;if(vals.Count==0)vals=new double[60];double max=Math.Max(1,vals.Max());var pts=string.Join(" ",vals.Select((v,i)=>$"{i*100.0/Math.Max(1,vals.Count-1):0.0},{58-v/max*52:0.0}"));return $"<svg viewBox='0 0 100 65' preserveAspectRatio='none'><path class='grid' d='M0 8H100M0 34H100M0 60H100'/><polyline id='{id}' class='line' style='stroke:{color}' points='{pts}'/></svg><div class='banner'>最近 60 秒</div>";}
static IResult LoginPage(HttpContext c,IAntiforgery af,string pass)=>Results.Content(LoginHtml(c,af,""),"text/html; charset=utf-8");
static string LoginHtml(HttpContext c,IAntiforgery af,string error){var csrf=af.GetAndStoreTokens(c).RequestToken??"";return $"<!doctype html><meta charset=utf-8><meta name=viewport content='width=device-width'><title>登录 · 洛链绽放</title><style>body{{font:16px system-ui;background:#f8f4f9;color:#35283a}}main{{max-width:390px;margin:12vh auto;background:white;padding:30px;border-radius:18px}}input{{width:100%;padding:13px;border:1px solid #ebdfeb;border-radius:10px;margin:16px 0}}button{{background:#d74787;color:white;border:0;border-radius:10px;padding:12px 18px}}</style><main><h2>洛链绽放 · 管理员登录</h2><p>输入 Docker 环境变量中的管理密码。</p><p style='color:#bd376b'>{E(error)}</p><form method=post><input type=hidden name=csrf value='{E(csrf)}'><input type=password name=password required autocomplete=current-password><button>登录管理台</button></form></main>";}
static async Task<bool> ValidCsrf(HttpContext c,IAntiforgery af){try{await af.ValidateRequestAsync(c);return true;}catch(AntiforgeryValidationException){return false;}}
static bool PasswordOk(string attempt,string expected){var a=SHA256.HashData(Encoding.UTF8.GetBytes(attempt));var b=SHA256.HashData(Encoding.UTF8.GetBytes(expected));return CryptographicOperations.FixedTimeEquals(a,b);}
static string E(string? s)=>WebUtility.HtmlEncode(s??"");static string Fmt(double? n)=>n==null?"—":MainWindowFormat(n.Value);static string Fmt(long? n)=>n==null?"—":MainWindowFormat(n.Value);static string MainWindowFormat(double n){string[] units={"B","KB","MB","GB","TB"};int i=0;while(n>=1024&&i<units.Length-1){n/=1024;i++;}return $"{n:0.##} {units[i]}";}

sealed class Store(string root,Microsoft.AspNetCore.DataProtection.IDataProtector protector){readonly string path=Path.Combine(root,"tunnels.bin");readonly object gate=new();public List<Tunnel> List{get{lock(gate){try{return File.Exists(path)?JsonSerializer.Deserialize<List<Tunnel>>(protector.Unprotect(File.ReadAllBytes(path)),Paths.Json)??new():new();}catch{return new();}}}}public void Save(List<Tunnel> list){lock(gate){var tmp=path+".tmp";File.WriteAllBytes(tmp,protector.Protect(JsonSerializer.SerializeToUtf8Bytes(list,Paths.Json)));File.Move(tmp,path,true);}}}
