sealed class LinuxTraffic:BackgroundService{readonly object gate=new();readonly Queue<double> rx=new(),tx=new();long oldRx,oldTx;DateTime old;LinuxTrafficRate value=new(null,null,new double[60],new double[60]);public LinuxTrafficRate Rate{get{lock(gate)return value;}}protected override async Task ExecuteAsync(CancellationToken ct){while(!ct.IsCancellationRequested){try{var (r,t)=Read();var now=DateTime.UtcNow;lock(gate){if(old!=default&&r>=oldRx&&t>=oldTx){rx.Enqueue((r-oldRx)/Math.Max(.1,(now-old).TotalSeconds));tx.Enqueue((t-oldTx)/Math.Max(.1,(now-old).TotalSeconds));while(rx.Count>60)rx.Dequeue();while(tx.Count>60)tx.Dequeue();value=new(rx.Last(),tx.Last(),rx.ToArray(),tx.ToArray());}oldRx=r;oldTx=t;old=now;}}catch{}await Task.Delay(1000,ct);}}static(long,long)Read(){long r=0,t=0;foreach(var line in File.ReadLines("/proc/net/dev").Skip(2)){var a=line.Split(':');if(a.Length!=2||a[0].Trim()=="lo")continue;var n=a[1].Split(' ',StringSplitOptions.RemoveEmptyEntries);if(n.Length>=9){r+=long.Parse(n[0]);t+=long.Parse(n[8]);}}return(r,t);}}
