sealed class FrpUpdater(string data,ILogger<FrpUpdater> log){readonly SemaphoreSlim gate=new(1,1);public string Installed=>File.Exists(Path.Combine(data,"engine-version.txt"))?File.ReadAllText(Path.Combine(data,"engine-version.txt")).Trim():"bundled";public async Task<string> Update(TunnelManager manager){await gate.WaitAsync();var ids=Array.Empty<string>();try{using var http=new HttpClient{Timeout=TimeSpan.FromSeconds(90)};http.DefaultRequestHeaders.UserAgent.ParseAdd("LoliaBloom/0.7.0");var json=await http.GetStringAsync("https://api.github.com/repos/Lolia-FRP/lolia-frp/releases/latest");using var doc=JsonDocument.Parse(json);var tag=doc.RootElement.GetProperty("tag_name").GetString()!;var arch=System.Runtime.InteropServices.RuntimeInformation.ProcessArchitecture==System.Runtime.InteropServices.Architecture.Arm64?"arm64":"amd64";var asset=doc.RootElement.GetProperty("assets").EnumerateArray().Single(x=>x.GetProperty("name").GetString()==$"LoliaFrp_linux_{arch}.tar.gz");var url=asset.GetProperty("browser_download_url").GetString()!;var hash=asset.GetProperty("digest").GetString()??"";if(!url.StartsWith("https://github.com/Lolia-FRP/lolia-frp/releases/download/",StringComparison.Ordinal)||!System.Text.RegularExpressions.Regex.IsMatch(hash,@"^sha256:[0-9a-fA-F]{64}$"))throw new Exception("FRP 官方发布信息缺少校验");using var download=await http.GetAsync(url,HttpCompletionOption.ResponseHeadersRead);download.EnsureSuccessStatusCode();if(download.Content.Headers.ContentLength>100*1024*1024)throw new Exception("FRP 更新包超过大小上限");await using var source=await download.Content.ReadAsStreamAsync();using var buffer=new MemoryStream();var chunk=new byte[65536];int read;while((read=await source.ReadAsync(chunk))>0){if(buffer.Length+read>100*1024*1024)throw new Exception("FRP 更新包超过大小上限");await buffer.WriteAsync(chunk.AsMemory(0,read));}var bytes=buffer.ToArray();if(!Convert.ToHexString(SHA256.HashData(bytes)).Equals(hash[7..],StringComparison.OrdinalIgnoreCase))throw new Exception("FRP SHA